 apply('005-form-two-expansion','0.3.0')
 p=ROOT/'content/library.json';d=json.loads(p.read_text());added=[];by_id={q['id']:i for i,q in enumerate(d['questions'])}
 for lid,items in workbooks.items():
  lesson=next(l for l in d['lessons'] if l['id']==lid);base=next(q for q in d['questions'] if q['topicIds']==[lid])
  for n,(prompt,answer,feedback) in enumerate(items,1):
   q={**base,'id':f'{lid}-wb-{n:02}','questionNumber':str(n),'content':prompt,'answerKey':answer,'markingGuide':feedback,'type':'short','options':[],'maximumMarks':2,'resourceKind':'workbook','sourceTitle':'SomaSmart original revision workbook','sourceReference':'Original Form Two workbook expansion'}
   if q['id'] in by_id:d['questions'][by_id[q['id']]]=q
   else:d['questions'].append(q)
   added.append(q)
 p.write_text(json.dumps(d,ensure_ascii=False,indent=2));(ROOT/'content/batches/006-form-two-workbooks.json').write_text(json.dumps({'questions':added},ensure_ascii=False,indent=2));print('Added',len(added),'distinct workbook questions.')
